package main

import "github.com/gin-gonic/gin"

func main() {
	r := gin.Default() // Engine + Logger + Recovery middleware
	r.GET("/ping", func(c *gin.Context) {
		c.JSON(200, gin.H{"message": "pong"})
	})
	_ = r.Run(":8080") // wraps http.ListenAndServe(addr, r)
	// GET /ping -> 200 {"message":"pong"}
}

package main

import "github.com/gin-gonic/gin"

func main() {
	r := gin.New()
	// Each of these is inserted into the method's radix tree once at startup.
	r.GET("/users/:id", getUser)      // static prefix /users/ + param node
	r.GET("/users/:id/posts", posts) // shares the /users/:id prefix
	r.GET("/health", health)          // separate branch
	_ = r.Run(":8080")
	// Matching /users/42 walks the tree in O(len(path)), not O(numRoutes).
}

