package main

import "github.com/gin-gonic/gin"

// Auth middleware: abort the chain on a missing token.
func Auth() gin.HandlerFunc {
	return func(c *gin.Context) {
		if c.GetHeader("Authorization") == "" {
			c.AbortWithStatusJSON(401, gin.H{"error": "unauthorized"})
			return // c.Abort() stops next handlers from running
		}
		c.Next() // token present -> continue the chain
	}
}

func main() {
	r := gin.Default()
	r.Use(Auth())
	r.GET("/secret", func(c *gin.Context) { c.JSON(200, gin.H{"ok": true}) })
	_ = r.Run(":8080")
}

