package main

import (
	"net/http"

	"github.com/gin-gonic/gin"
)

// ErrorHandler runs the chain, then emits one response for the first error.
func ErrorHandler() gin.HandlerFunc {
	return func(c *gin.Context) {
		c.Next() // run downstream handlers first
		if len(c.Errors) > 0 {
			c.JSON(http.StatusInternalServerError, gin.H{
				"error": c.Errors.Last().Error(),
			})
		}
	}
}

func Auth() gin.HandlerFunc {
	return func(c *gin.Context) {
		if c.GetHeader("Authorization") == "" {
			c.AbortWithStatusJSON(http.StatusUnauthorized, gin.H{"error": "unauthorized"})
			return // Abort stops the chain here
		}
		c.Next()
	}
}

func main() {
	r := gin.New()
	r.Use(gin.Logger(), gin.Recovery(), ErrorHandler())

	v1 := r.Group("/api/v1")
	v1.GET("/health", func(c *gin.Context) { c.JSON(200, gin.H{"ok": true}) })

	admin := v1.Group("/admin")
	admin.Use(Auth())
	admin.GET("/report", func(c *gin.Context) {
		c.Error(gin.Error{Err: http.ErrBodyNotAllowed, Type: gin.ErrorTypePublic})
		// no explicit response: ErrorHandler will emit the 500
	})

	_ = r.Run(":8080")
}

