package solution

import (
	"net/http/httptest"
	"testing"

	"github.com/gin-gonic/gin"
)

func ctxWithQuery(q string) *gin.Context {
	gin.SetMode(gin.TestMode)
	c, _ := gin.CreateTestContext(httptest.NewRecorder())
	c.Request = httptest.NewRequest("GET", "/items?"+q, nil)
	return c
}

func TestBindPageDefault(t *testing.T) {
	p, err := bindPage(ctxWithQuery("offset=5"))
	if err != nil {
		t.Fatalf("unexpected err: %v", err)
	}
	if p.Limit != 20 || p.Offset != 5 {
		t.Fatalf("got %+v want {20 5}", p)
	}
}

func TestBindPageInvalid(t *testing.T) {
	if _, err := bindPage(ctxWithQuery("limit=999")); err == nil {
		t.Fatal("expected validation error for limit=999")
	}
}

