package solution

import (
	"net/http"

	"github.com/gin-gonic/gin"
)

// RequireToken aborts with 401 unless the Authorization header equals want.
func RequireToken(want string) gin.HandlerFunc {
	return func(c *gin.Context) {
		if c.GetHeader("Authorization") != want {
			c.AbortWithStatusJSON(http.StatusUnauthorized, gin.H{"error": "unauthorized"})
			return
		}
		c.Set("token", want) // available to downstream handlers via c.Get
		c.Next()
	}
}

